      "module": "vision",
      "passage_id": "PASS-8da032d63c954c0ce3d82598",
      "fact_fields": ["vision.diplopia.present", "vision.diplopia.within_20_degrees"],
      "licence_pathway": "both",
      "finding": "established_restriction",
      "conclusion": "The verified facts confirm the presence of diplopia within 20 degrees of central fixation. Guideline AFTD2022-VIS-COM-007 section 10.3 states a person is not fit if they experience any diplopia (other than physiological) within 20 degrees from central fixation."
